wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::inference_llm::infer;

struct Node;

/// Truncate `s` to at most `max` bytes without splitting a UTF-8 char.
fn truncate_chars(s: &str, max: usize) -> String {
    if s.len() <= max {
        return s.to_string();
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s[..end].to_string()
}

/// Map free model text onto the closed intent set. The enum has no "other"
/// case, so adversarial text cannot widen the set: anything unrecognised
/// collapses to `Unknown`.
fn parse_intent(raw: &str) -> Intent {
    let t = raw.trim().to_ascii_lowercase();
    if t.contains("billing") {
        Intent::BillingQuestion
    } else if t.contains("technical") || t.contains("support") {
        Intent::TechnicalSupport
    } else if t.contains("account") {
        Intent::AccountChange
    } else if t.contains("general") || t.contains("inquiry") {
        Intent::GeneralInquiry
    } else {
        Intent::Unknown
    }
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // `requires len(value.text) <= 4000` holds of every input by contract.

        let system = "You are a message classifier for a customer-support system. \
Read the user's message and reply with exactly one of these words and nothing else: \
billing_question, technical_support, account_change, general_inquiry, unknown.";

        let intent = parse_intent(&infer(system, &message.text, "classify"));

        // `ensures len(question) <= 512`: bound the free-text residual.
        let question = truncate_chars(&message.text, 512);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
```

